const menu=document.querySelector('.menu'),nav=document.querySelector('.navlinks');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open);menu.textContent=open?'Close':'Menu'});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu';menu.focus()}});
const conversations={
 announcements:{icon:'P',heading:'Announcements',sub:'From your provider · For the whole program',label:'Pinned announcement',title:'Before our next session',body:'Bring your practice work. We’ll look at it together before starting the next exercise.',hint:'Official updates arrive in the app and by email.',detail:'Only the provider posts here. Pinned updates stay at the top, and announcements have their own unread count.'},
 discussion:{icon:'C',heading:'Program discussion',sub:'For everyone enrolled',label:'Between sessions',title:'Can we compare our first attempts?',body:'Post your practice work or ask the group a question. Replies stay in a thread, so you can follow the conversation.',hint:'Get notified when someone replies to you.',detail:'Replies to you trigger a notification. Other discussion is gathered into a digest, sent at most once a day and skipped if you have already caught up in the app.'},
 messages:{icon:'P',heading:'Private messages',sub:'You and your provider',label:'A private conversation',title:'A question about what to bring',body:'Ask the provider directly. Your conversation is linked to the program, so you both know which program you mean.',hint:'Your question stays out of the program discussion.',detail:'Program-linked threads keep private questions together. Search your inbox by program and see which conversations have unread messages.'},
 live:{icon:'L',heading:'Live session chat',sub:'Inside the video room',label:'During your session',title:'Could you show that step again?',body:'Ask while the provider is sharing their screen. Use the chat beside the video without interrupting the demonstration.',hint:'See who is typing while the session is on.',detail:'Live chat belongs to the session you are attending. You can switch the sidebar between messages and the people in the room.'}
};
const tabs=[...document.querySelectorAll('[data-chat]')];
function selectChat(tab,focus=false){const data=conversations[tab.dataset.chat];tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',selected);t.tabIndex=selected?0:-1});const panel=document.getElementById('chat-panel');panel.setAttribute('aria-labelledby',tab.id);panel.innerHTML=`<div class="chat-header"><span class="avatar">${data.icon}</span><div><strong>${data.heading}</strong><small>${data.sub}</small></div></div><div class="bubble"><span class="pin">${data.label}</span><strong>${data.title}</strong><p>${data.body}</p></div><div class="chat-hint">✓ &nbsp; ${data.hint}</div><p class="comms-copy">${data.detail}</p>`;if(focus)tab.focus()}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectChat(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowDown'||e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowUp'||e.key==='ArrowLeft')next=(i-1+tabs.length)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectChat(tabs[next],true)}})});
const faqSearch=document.querySelector('#faq-search');faqSearch?.addEventListener('input',()=>{let count=0;document.querySelectorAll('[data-faq]').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(faqSearch.value.trim().toLowerCase());if(!row.hidden)count++});document.querySelector('#faq-empty').hidden=count>0;document.querySelector('#faq-count').textContent=count+' answers'});
const filters=[...document.querySelectorAll('[data-filter]')];filters.forEach(btn=>btn.addEventListener('click',()=>{filters.forEach(b=>b.setAttribute('aria-pressed',b===btn));let count=0;document.querySelectorAll('[data-group]').forEach(card=>{card.hidden=btn.dataset.filter!=='all'&&card.dataset.group!==btn.dataset.filter;if(!card.hidden)count++});document.querySelector('#guide-count').textContent=count+' subject guides'}));
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches && 'IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:.4,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:600,easing:'cubic-bezier(.2,.7,.2,1)'});observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.split,.category,.step,.comms-grid,.teach-block,.trust-item,.faq-grid,.provider-demo').forEach(el=>observer.observe(el))}
